WITH entries(source_kind, principal_key, permission) AS (
    VALUES 
        (CAST(#{entry.sourceKind} AS text), CAST(#{entry.principalKey} AS text), CAST(#{entry.permission} AS text))

)
SELECT e.source_kind || ':' || e.principal_key || ':' || e.permission FROM entries e
WHERE (e.source_kind = 'SPACE' AND EXISTS (SELECT 1 FROM kb_space_acl a WHERE a.space_id = #{spaceId}
    AND a.principal_key = e.principal_key AND a.permission = e.permission))
OR (e.source_kind = 'DOCUMENT' AND EXISTS (SELECT 1 FROM kb_document_acl a WHERE a.doc_id = #{documentId,jdbcType=BIGINT}
    AND a.principal_key = e.principal_key AND a.permission = e.permission))

mapper.sql:

WITH diagnostic_rows(source_kind, principal_key, permission) AS (


            VALUES (CAST(#{row.sourceKind} AS text), CAST(#{row.principalKey} AS text), CAST(#{row.permission} AS text))

        SELECT NULL::text, NULL::text, NULL::text WHERE FALSE

), diagnostic_space AS (
    SELECT CAST(#{spaceId} AS bigint) AS space_id, principal_key, permission FROM diagnostic_rows WHERE source_kind = 'SPACE'
), diagnostic_document AS (
    SELECT CAST(#{documentId,jdbcType=BIGINT} AS bigint) AS doc_id, principal_key, permission FROM diagnostic_rows WHERE source_kind = 'DOCUMENT'
)

